import{_ as e,H as i,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"04 | 索罗斯的炼金术：利用错误的暴利艺术","description":"","frontmatter":{},"headers":[{"level":2,"title":"市场永远是错的：打破均衡的幻想","slug":"市场永远是错的-打破均衡的幻想","link":"#市场永远是错的-打破均衡的幻想","children":[]},{"level":2,"title":"特斯拉、比特币与反身性循环","slug":"特斯拉、比特币与反身性循环","link":"#特斯拉、比特币与反身性循环","children":[]},{"level":2,"title":"1992 年：那一记封喉的做空","slug":"_1992-年-那一记封喉的做空","link":"#_1992-年-那一记封喉的做空","children":[{"level":3,"title":"量化分析（盈亏比计算）","slug":"量化分析-盈亏比计算","link":"#量化分析-盈亏比计算","children":[]}]},{"level":2,"title":"如何把哲学写进代码？","slug":"如何把哲学写进代码","link":"#如何把哲学写进代码","children":[]},{"level":2,"title":"索罗斯的遗产：易错性","slug":"索罗斯的遗产-易错性","link":"#索罗斯的遗产-易错性","children":[]},{"level":2,"title":"AI 量化策略建议","slug":"ai-量化策略建议","link":"#ai-量化策略建议","children":[]},{"level":2,"title":"本讲金句弹幕","slug":"本讲金句弹幕","link":"#本讲金句弹幕","children":[]},{"level":2,"title":"课后思考题","slug":"课后思考题","link":"#课后思考题","children":[]}],"relativePath":"人人都用得上的AI量化思维课/04｜索罗斯的炼金术：利用错误的暴利艺术.md","filePath":"人人都用得上的AI量化思维课/04｜索罗斯的炼金术：利用错误的暴利艺术.md","lastUpdated":1795541548000}'),p={name:"人人都用得上的AI量化思维课/04｜索罗斯的炼金术：利用错误的暴利艺术.md"};function r(n,l,o,h,s,u){return i(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="_04-索罗斯的炼金术-利用错误的暴利艺术" tabindex="-1">04 | 索罗斯的炼金术：利用错误的暴利艺术 <a class="header-anchor" href="#_04-索罗斯的炼金术-利用错误的暴利艺术" aria-label="Permalink to &quot;04 | 索罗斯的炼金术：利用错误的暴利艺术&quot;">​</a></h1><p>你好，我是陈旸。</p><p>上一讲，我们见识了西蒙斯如何用冷冰冰的数据，挖掘市场的微小漏洞。今天，我们要从微观的捡芝麻，转向宏观的屠龙。我们要聊的这个人，乔治·索罗斯，曾在一夜之间赚走了 10 亿英镑，逼得英国央行举手投降；他在 1997 年横扫东南亚，让无数国家的货币体系崩溃。他被称为金融大鳄，也被称为哲学家。</p><p>你可能会问：“这种宏观投机的大佬，跟我们做量化有什么关系？他又不看 K 线，也不跑Python 代码。”如果你这么想，那你就错过了一个最重要的量化模型。</p><p>索罗斯的思维方式，其实解决了量化交易中一个最棘手的难题：当市场疯了的时候，原本有效的模型为什么会失效？以及，我们该如何骑上泡沫的背脊？今天，我们就用量化的手术刀，解剖索罗斯那本晦涩难懂的《金融炼金术》。</p><h2 id="市场永远是错的-打破均衡的幻想" tabindex="-1">市场永远是错的：打破均衡的幻想 <a class="header-anchor" href="#市场永远是错的-打破均衡的幻想" aria-label="Permalink to &quot;市场永远是错的：打破均衡的幻想&quot;">​</a></h2><p>在传统的经济学教科书（以及早期的量化模型）里，有一个核心假设叫：一般均衡理论。它认为：</p><ol><li><p>市场是理性的。</p></li><li><p>价格围绕价值上下波动。</p></li><li><p>如果价格偏离了价值，市场会自动把它拉回来（均值回归）。</p></li></ol><p>这就像一个恒温器：温度高了，空调就制冷；温度低了，暖气就加热。系统总是趋向于稳定。如果世界真是这样，那西蒙斯和巴菲特就够用了。但索罗斯冷笑一声：“世界经济史是一部基于假象和谎言的连续剧。”</p><p>索罗斯认为，传统经济学忽略了一个核心变量：人的偏见。在物理世界，你看着天气，天气不会因为你看着它而改变。但在金融世界，你看好一支股票，你买入它，股价就会涨；股价涨了，基本面（融资能力、品牌形象）竟然真的变好了，于是你更看好它……这就是著名的反身性理论。</p><p>用控制论的语言翻译一下： 传统市场理论假设市场是负反馈系统（涨多了会跌，趋向稳定）；索罗斯认为市场经常变成正反馈系统（涨了因，因又推高果，越涨越涨，直到崩溃）。想象你在 KTV 唱歌，如果你把麦克风（输入）靠得离音箱（输出）太近，会发生什么？啸叫。 声音会被无限放大，直到震破耳膜。索罗斯做的，就是寻找那个麦克风靠近音箱的时刻。</p><h2 id="特斯拉、比特币与反身性循环" tabindex="-1">特斯拉、比特币与反身性循环 <a class="header-anchor" href="#特斯拉、比特币与反身性循环" aria-label="Permalink to &quot;特斯拉、比特币与反身性循环&quot;">​</a></h2><p>为了让你听懂这个抽象的哲学，我们不讲 1992 年的英镑，我们讲讲大家都熟悉的特斯拉（或者任何一个大牛股）。在量化思维里，一个标准的索罗斯式正反馈循环是这样运行的：</p><p>阶段 1：起步（偏见引入）</p><p>特斯拉刚开始只是一个亏损的电动车厂。但马斯克讲了一个性感的故事（火星、清洁能源）。此时，股价开始上涨。</p><ul><li><ul><li>传统量化模型（价值因子）：* 这是一个垃圾股，做空它！</li></ul></li><li><ul><li>索罗斯思维：* 等等，看故事能不能自我实现。</li></ul></li></ul><p>阶段 2：加速（自我强化）</p><p>股价上涨，特斯拉市值变大了。神奇的事情发生了：因为市值大，特斯拉可以高位增发股票，融到了几十亿美元的真金白银。有了钱，它真的建起了超级工厂，产能真的提升了，车真的造出来了。原本是吹牛的基本面，因为股价的上涨，变成了真的基本面。</p><p>阶段 3：疯狂（正反馈高潮）</p><p>基本面变好，吸引更多机构买入，股价继续暴涨。股价暴涨，吸引更好的人才，获得更低的贷款利率，品牌成为全球顶流，基本面好上加好。</p><ul><li><ul><li>此时的现象：* 所有看空它的量化模型（均值回归策略）全部被打爆。</li></ul></li><li><ul><li>索罗斯的操作：* 在泡沫中游泳。 他知道这是泡沫，但他不会做空，他会做多，因为正反馈还没断。</li></ul></li></ul><p>阶段 4：崩溃（反向反身性）</p><p>直到某一个临界点（比如产能瓶颈、宏观加息），故事讲不下去了。股价下跌 =&gt; 融资困难 =&gt;工厂停工 =&gt; 业绩下滑 =&gt; 股价更跌。原来的正反馈螺旋，瞬间变成向下的死亡螺旋。</p><p>量化视角的启示：</p><p>所谓的基本面，并不是客观存在的锚。价格本身就是基本面的一部分。如果你在做量化因子分析时，只看财务报表（滞后数据），而不看价格动量对基本面的反作用，你就会死在黎明前的黑暗里。</p><h2 id="_1992-年-那一记封喉的做空" tabindex="-1">1992 年：那一记封喉的做空 <a class="header-anchor" href="#_1992-年-那一记封喉的做空" aria-label="Permalink to &quot;1992 年：那一记封喉的做空&quot;">​</a></h2><p>理解了理论，我们再来看索罗斯的封神之战——狙击英镑。这根本不是一次赌博，而是一次基于逻辑的必然性套利。</p><p>背景：1990 年代，欧洲搞了一体化，英国加入了欧洲汇率机制（ERM）。这意味着，英镑必须锁定马克，汇率不能波动太大。但是，德国为了抑制通胀，把利息定得很高；英国经济衰退，急需降息刺激。</p><p>矛盾（失衡点）： 英国如果不加息，英镑就会跌穿下限（违反 ERM）；如果加息，英国经济就会崩盘。这就形成了一个不可能三角。索罗斯敏锐地嗅到了这个不稳定的均衡。他知道，英国央行在死撑。 这种死撑，就是市场最大的错误定价。</p><h3 id="量化分析-盈亏比计算" tabindex="-1">量化分析（盈亏比计算） <a class="header-anchor" href="#量化分析-盈亏比计算" aria-label="Permalink to &quot;量化分析（盈亏比计算）&quot;">​</a></h3><p>如果做空英镑：</p><ul><li><p>情况 A（大概率）：英国撑不住，退出 ERM，英镑暴跌。赚几十倍。</p></li><li><p>情况 B（小概率）：英国死撑到底，英镑维持原价。亏损极小（只是付一点利息成本）。</p></li></ul><p>这是一笔风险有限，收益无限的单向赌博。当索罗斯的助手德鲁肯米勒跑来说：“乔治，我算过了，我们要把所有资金都压上去做空英镑。”索罗斯说出了那句流传千古的名言：“这就是你的建仓规模？要想赚钱，你必须冲上去锁喉。”</p><p>最终，索罗斯动用了两倍杠杆，建立了 100 亿美元的空头头寸。那一晚，英国央行动用了几百亿美元的外汇储备买入英镑，但在索罗斯引领的全球空头大军面前，如同杯水车薪。第二天，英国宣布退出 ERM，英镑暴跌。索罗斯净赚 10 亿美元。</p><p>量化思维的第二次顿悟：胜率不重要，赔率和仓位才重要。很多量化策略追求高胜率（如网格交易），但一次黑天鹅就亏光。索罗斯追求的是非对称机会——当我错了，我亏一点点；当我对了，我要赚这辈子都花不完的钱。</p><h2 id="如何把哲学写进代码" tabindex="-1">如何把哲学写进代码？ <a class="header-anchor" href="#如何把哲学写进代码" aria-label="Permalink to &quot;如何把哲学写进代码？&quot;">​</a></h2><p>你可能会问：“道理我都懂，但在 QMT 里怎么写索罗斯策略？”索罗斯的反身性很难直接编程，但我们可以捕捉它的影子。在现代量化中，这演变成了拥挤度和趋势跟随策略。</p><ol><li>拥挤度指标</li></ol><p>索罗斯最喜欢在趋势最疯狂的时候离场。量化如何判断疯狂？</p><ul><li><p>换手率因子：当一只股票换手率达到历史极值，说明所有想买的人都买进去了，剩下的全是潜在卖家。</p></li><li><p>相关性因子：当所有股票不管好坏都在涨，市场相关性趋近于 1，说明是情绪驱动，而非价值驱动。</p></li></ul><ol start="2"><li>动量加速</li></ol><p>普通的动量策略是涨了就买。索罗斯式的动量策略是看二阶导数——涨得越来越快。当价格呈现指数级拉升（Log-Periodic Power Law，LPPL 模型），往往预示着正反馈即将崩塌。</p><ol start="3"><li>情绪分析</li></ol><p>利用 AI 读取新闻和社交媒体。当媒体充满了“新范式、改变世界、这次不一样”等词汇时，这就是偏见的量化读数。AI 可以给这种偏见打分，当偏见分数过高时，就是反转的信号。</p><p>在《QMT 实战训练营》里，我会教你如何计算 “RSI 背离、乖离率以及资金流向”，这些其实就是微观层面的索罗斯指标。</p><h2 id="索罗斯的遗产-易错性" tabindex="-1">索罗斯的遗产：易错性 <a class="header-anchor" href="#索罗斯的遗产-易错性" aria-label="Permalink to &quot;索罗斯的遗产：易错性&quot;">​</a></h2><p>最后，我想谈谈索罗斯思维中最核心，也最容易被忽视的一点：易错性。西蒙斯相信模型是完美的，巴菲特相信公司是完美的。但索罗斯相信：我是错的。他曾说：“我之所以富有，是因为我知道我什么时候错了。”</p><p>在他背部剧烈疼痛的时候，他会清空仓位，因为他相信身体在向他报警，说明有些潜意识发现的风险还没被显意识捕捉到。这听起来很迷信，但翻译成量化语言，这就是动态风控。很多量化交易者死扛亏损，是因为他们太相信回测数据，太相信模型。他们会说：“历史数据显示这里应该反弹了，模型不会错，是市场错了。”这就是死期。</p><p>索罗斯教给我们的是：模型只是你对世界的一种偏见。当市场走势证伪了你的假设时，第一时间砍仓，不要辩解。在索罗斯的基金里，没有自尊心这个词。今天做多，明天发现错了，立马反手做空，毫不脸红。这种极度的反人性的灵活性，才是量化交易员的最高境界。</p><h2 id="ai-量化策略建议" tabindex="-1">AI 量化策略建议 <a class="header-anchor" href="#ai-量化策略建议" aria-label="Permalink to &quot;AI 量化策略建议&quot;">​</a></h2><p>这一讲稍微有点抽象，我们总结一下索罗斯给我们的三个量化锦囊：</p><ol><li><p>寻找正反馈：不要轻易做空泡沫。在泡沫初期和中期，反身性会让泡沫越来越大。要学会利用泡沫，而不是过早地站在泡沫的对立面。</p></li><li><p>寻找不稳定的均衡：当某个价格被政策强行固定（如固定汇率、甚至某种被操纵的股价），而基本面又不支持时，这就是最大的暴利机会。</p></li><li><p>活着承认错误：不管你的 AI 模型回测多完美，一定要给它装一个红色按钮。当实盘亏损超过阈值，无条件止损。因为市场总有你不知道的偏见。</p></li></ol><h2 id="本讲金句弹幕" tabindex="-1">本讲金句弹幕 <a class="header-anchor" href="#本讲金句弹幕" aria-label="Permalink to &quot;本讲金句弹幕&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%94%A8%E5%BE%97%E4%B8%8A%E7%9A%84AI%E9%87%8F%E5%8C%96%E6%80%9D%E7%BB%B4%E8%AF%BE/images/04/1.png" alt=""></a></p><h2 id="课后思考题" tabindex="-1">课后思考题 <a class="header-anchor" href="#课后思考题" aria-label="Permalink to &quot;课后思考题&quot;">​</a></h2><p>回想一下最近的金融市场，比如一波 AI 概念股的暴涨，或者是虚拟 IP 盲盒概念股的暴涨。你能找出其中的反身性循环吗？是哪个故事启动了上涨？上涨又是如何反过来强化这个故事的？如果是你，你会选择在哪个节点切入，又在哪个信号出现时离场？</p><p>欢迎你把你的想法留在评论区，也欢迎你把这节课分享给对量化感兴趣的朋友。下一讲，我们将离开哲学的云端，落回到数学的地面。既然索罗斯说：“当我对了，我要赚大钱”。那么问题来了：到底下注多少才叫赚大钱，同时又不会把自己赔光？我们将介绍那个让无数天才破产，又让无数天才暴富的终极数学公式——凯利公式。</p>',57)])])}const _=e(p,[["render",r]]);export{c as __pageData,_ as default};
